            "customer_payment_term_id",
          ],
          false,
        );
      }
    }
  }
};

(async () => {
  try {
    console.log("onmounted");
    const status = await this.getValue("customer_status");
    const pageStatus = this.isAdd
      ? "Add"
      : this.isEdit
        ? "Edit"
        : this.isView
          ? "View"
          : (() => {
              this.$message.error("Invalid page status");
            })();
    console.log("page status", pageStatus);
    let organizationId = this.getVarGlobal("deptParentId");
    if (organizationId === "0") {
      organizationId = this.getVarSystem("deptIds").split(",")[0];
    }

    this.setData({ organization_id: organizationId, page_status: pageStatus });

    switch (pageStatus) {
      case "Add":
        this.display(["active_status"]);
        this.setData({ is_accurate: 1 });
        await checkAccIntegrationType(organizationId);
        break;

      case "Edit":
        await disabledField();
        await showStatusHTML(status);
        this.disabled(
          [
            "customer_id",
            "customer_com_reg_no",
            "customer_com_name",
            'customer_com_name2',
            "customer_com_reg_no",
            "customer_com_old_reg_no",
            "business_type_id",
            "customer_irbm_id",
            "customer_agent_id",
            "customer_currency_id",
            "customer_payment_term_id",
          ],
          true,
        );
        await checkAccIntegrationType(organizationId);
        break;

      case "View":
        await showStatusHTML(status);
        await isViewMode();
        break;
    }
  } catch (error) {
    this.$message.error(error);
  }
})();

setTimeout(async () => {
  const maxRetries = 10;
  const interval = 500;
  for (let i = 0; i < maxRetries; i++) {
    const op = await this.onDropdownVisible("customer_id_type", true);
    if (op != null) break;
    await new Promise((resolve) => setTimeout(resolve, interval));
  }
  function getDefaultItem(arr) {
    return arr?.find((item) => item?.item?.is_default === 1);
  }
  var params = this.getComponent("customer_id");
  const { options } = params;

  const optionsData = this.getOptionData("customer_id_type") || [];
  const defaultData = getDefaultItem(optionsData);
  if (options?.canManualInput) {
    this.setOptionData("customer_id_type", [
      { label: "Manual Input", value: -9999 },
      ...optionsData,
    ]);
    if (this.isAdd) {
      this.setData({
        customer_id_type: defaultData ? defaultData.value : -9999,
      });
    }
  } else if (defaultData) {
    if (this.isAdd) {
      this.setData({ customer_id_type: defaultData.value });
    }
  }
}, 200);

