(async () => {
  try {
    const rowIndex = Number(arguments[0].rowIndex);
    const mobileNumber = arguments[0].value;
    const rowId = arguments[0].row && arguments[0].row.id;

    if (!mobileNumber) return;

    const currentCustomerId = this.getValue("id");

